  useEffect(() => {
    // 초기 로드: GitHub에서 최신 레이아웃 로드 → 실패 시 localStorage 폴백
    const loadLayout = async () => {
      try {
        const resp = await fetch(`https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main/public/data/layout.json?t=${Date.now()}`);
        if (resp.ok) {
          const data = await resp.json();
          if (data && data.R && data.R.length > 0) {
            const jsonStr = JSON.stringify(data);
            safeStorage.setItem('pbk_layout_data', jsonStr);
            setLayoutData(data);
            console.log('[Layout] GitHub에서 최신 레이아웃 로드, 랙:', data.R.length);
            return;
          }
        }
      } catch(ex) { console.log('[Layout] GitHub fetch 실패, localStorage 폴백:', ex.message); }
      try {
        const saved = safeStorage.getItem('pbk_layout_data');
        if (saved) setLayoutData(JSON.parse(saved));
      } catch(ex) {}
    };
    loadLayout();
  }, []);

  useEffect(() => {
    const handleLayoutMessage = (e) => {
      if (!e.data || !e.data.type) return;
      if (e.data.type === 'layoutClear') {
        try { safeStorage.removeItem('pbk_layout_data'); } catch(ex) {}
        setLayoutData(null);
      }
      if (e.data.type === 'layoutSave') {
        try {
          console.log('[Layout] 저장 이벤트 수신, 데이터 길이:', e.data.data?.length);
          safeStorage.setItem('pbk_layout_data', e.data.data);
          setLayoutData(JSON.parse(e.data.data));
          uploadLayoutToGitHub(e.data.data);
        } catch(ex) { console.error('[Layout] 저장 처리 오류:', ex); }
      }
      if (e.data.type === 'layoutReady') {
        const sendToIframe = (jsonStr) => {
          try {
            const parsed = JSON.parse(jsonStr);
            if (parsed.R && parsed.R.length > 0 && layoutIframeRef.current) {
              layoutIframeRef.current.contentWindow.postMessage({ type: 'layoutLoad', data: jsonStr }, '*');
            }
          } catch(ex) {}
        };
        // GitHub에서 최신 레이아웃 로드 → 실패 시 localStorage 폴백
        fetch(`https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main/public/data/layout.json?t=${Date.now()}`)
          .then(r => r.ok ? r.text() : null)
          .then(text => {
            if (text) {
              safeStorage.setItem('pbk_layout_data', text);
              setLayoutData(JSON.parse(text));
              sendToIframe(text);
            } else {
              const saved = safeStorage.getItem('pbk_layout_data');
              if (saved) sendToIframe(saved);
            }
          }).catch(() => {
            const saved = safeStorage.getItem('pbk_layout_data');
            if (saved) sendToIframe(saved);
          });
      }
    };
    window.addEventListener('message', handleLayoutMessage);
    return () => window.removeEventListener('message', handleLayoutMessage);
  }, []);

  // GitHub layout.json 자동 업로드
  // 토큰은 소스에 포함하지 않고 localStorage에서 읽음.
  // 브라우저 콘솔에서 한 번 실행: localStorage.setItem('pbk_gh_token', '토큰값')
  const uploadLayoutToGitHub = async (jsonStr) => {
    console.log('[GitHub Layout] 업로드 시도, 데이터 길이:', jsonStr?.length);
    const TOKEN = safeStorage.getItem('pbk_gh_token');
    if (!TOKEN) { console.warn('[GitHub Layout] 토큰 미설정'); showToast('GitHub 토큰 미설정 (localStorage: pbk_gh_token)', 'error'); return; }
    const OWNER = 'wjdwlals9545-arch';
    const REPO = 'pbk-warehouse';
    const PATH = 'public/data/layout.json';
    const API = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${PATH}`;
    try {
      let sha;
      const getResp = await fetch(API, {
        headers: { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json' }
      });
      if (getResp.ok) { const info = await getResp.json(); sha = info.sha; console.log('[GitHub Layout] 기존 파일 SHA:', sha); }
      const content = btoa(unescape(encodeURIComponent(jsonStr)));
      const body = { message: 'Update layout.json from dashboard', content, ...(sha ? { sha } : {}) };
      const putResp = await fetch(API, {
        method: 'PUT',
        headers: { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
      if (putResp.ok) { console.log('[GitHub Layout] 성공'); showToast('☁️ 배치도 GitHub 업로드 완료', 'success'); }
      else { const t = await putResp.text(); console.error('[GitHub Layout] 실패:', putResp.status, t.slice(0,200)); showToast('GitHub 업로드 실패: ' + t.slice(0,60), 'error'); }
    } catch (err) { console.error('[GitHub Layout] 오류:', err); showToast('GitHub 업로드 오류: ' + err.message, 'error'); }
  };

  // GitHub에 Stock/OpenPO 데이터 업로드 (JSON)
  const uploadDataToGitHub = async (path, data, label) => {
    const TOKEN = safeStorage.getItem('pbk_gh_token');
    if (!TOKEN) return;
    const OWNER = 'wjdwlals9545-arch';
    const REPO = 'pbk-warehouse';
    const API = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${path}`;
    try {
      let sha;
      const getResp = await fetch(API, {
        headers: { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json' }
      });
      if (getResp.ok) { const info = await getResp.json(); sha = info.sha; }
      const jsonStr = JSON.stringify(data);
      const content = btoa(unescape(encodeURIComponent(jsonStr)));
      const body = { message: `Update ${label} from dashboard`, content, ...(sha ? { sha } : {}) };
      const putResp = await fetch(API, {
        method: 'PUT',
        headers: { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
      if (putResp.ok) showToast(`☁️ ${label} GitHub 업로드 완료`, 'success');
    } catch (err) { console.error(`GitHub upload error (${label}):`, err); }
  };

  // ──── 폰 스캔(kitting.html) 이벤트 병합 ────
  // 아웃룩 감시(outlook_watcher.py)가 올린 신규 오더/완료 이벤트를 주기적으로 반영한다.
  // - orders: 생산계획 메일의 orders_all.csv → 없는 오더는 새로 등록
  // - done  : [Warehouse][Kitting 완료] 메일 수신시각 → 완료 처리 + 리드타임/사이클타임 계산
  // 적용한 항목은 pbk_mail_applied 에 기록해 같은 이벤트를 두 번 반영하지 않는다.
  const applyMailEvents = async () => {
    try {
      const resp = await fetch(`https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main/public/data/kitting_mail_events.json?t=${Date.now()}`);
      if (!resp.ok) return;
      const doc = await resp.json();
      const omap = (doc && doc.orders) || {};
      const dmap = (doc && doc.done) || {};
      if (!Object.keys(omap).length && !Object.keys(dmap).length) return;

      const applied = new Set(safeParse(safeStorage.getItem('pbk_mail_applied'), []));
      const krDate = (iso) => new Date(iso).toLocaleDateString('ko-KR', { timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\. /g, '-').replace('.', '');
      const picFor = (iso) => {
        const d = String(iso || '').slice(0, 10);
        return (d && d >= '2026-03-19' && d < '2026-07-01') ? 'HJ. Kim' : (tempHumidityRecorder || 'JM. Jung');
      };

      const curK = safeParse(safeStorage.getItem('pbk_kitting_data'), []);
      const seenK = new Set(curK.map(k => String(k.productionOrder)));
      const newlyApplied = [];
      let addedK = 0, doneK = 0;

      // 1) 신규 오더 등록
      const mergedK = curK.slice();
      Object.keys(omap).forEach(o => {
        const sig = 'o:' + o;
        if (seenK.has(o) || applied.has(sig)) return;
        const b = omap[o];
        mergedK.push({
          id: 'ml-' + o,
          productionOrder: o,
          model: modelFromMaterial(b.mat),
          materialNum: b.mat || '',
          materialDesc: b.desc || '',
          qty: b.q != null ? b.q : null,
          createdOn: b.created || '',
          basicStartDate: b.created || '',
          basicFinishDate: b.finish || '',
          worker: b.sup || '',
          warehousePic: picFor(b.start),
          isUrgent: !!b.urgent,
          status: 'in-progress',
          startedAt: b.start || null,
          completedAt: null,
          leadTimeDays: null,
          createdAt: b.start || null,
          source: 'mail-auto',
        });
        seenK.add(o);
        newlyApplied.push(sig);
        addedK++;
      });

      // 2) 완료 처리
      const finalK = mergedK.map(k => {
        const o = String(k.productionOrder);
        const ts = dmap[o];
        const sig = 'd:' + o + '@' + ts;
        if (!ts || applied.has(sig) || k.completedTs === ts) return k;
        const st = k.startedAt || (omap[o] && omap[o].start);
        newlyApplied.push(sig);
        doneK++;
        return { ...k, status: 'completed', completedAt: krDate(ts), completedTs: ts,
                 leadTimeDays: st ? getLeadTimeDays(parseTs(st), parseTs(ts)) : k.leadTimeDays,
                 source: k.source || 'mail-auto' };
      });

      // 3) 불출 Cycle 동기화 (없으면 생성, 완료시각 반영)
      const curP = safeParse(safeStorage.getItem('pbk_pick_cycles'), []);
      const idxP = new Map(curP.map((x, i) => [String(x.productionOrder || x.orderId), i]));
      const mergedP = curP.slice();
      Object.keys(omap).forEach(o => {
        const b = omap[o];
        const ts = dmap[o];
        if (idxP.has(o)) {
          if (ts) {
            const cur = mergedP[idxP.get(o)];
            if (cur.completed !== ts) {
              mergedP[idxP.get(o)] = { ...cur, status: 'completed', completed: ts,
                cycleMin: cur.startTime ? getWorkingMinutes(parseTs(cur.startTime), parseTs(ts)) : cur.cycleMin };
            }
          }
          return;
        }
        mergedP.push({
          id: 'ml-p-' + o,
          productionOrder: o,
          model: modelFromMaterial(b.mat),
          materialNum: b.mat || '',
          materialDesc: b.desc || '',
          qty: b.q != null ? b.q : null,
          basicStartDate: b.created || '',
          worker: b.sup || '',
          warehousePic: picFor(b.start),
          received: b.start || null,
          startTime: b.start || null,
          completed: ts || null,
          cycleMin: (b.start && ts) ? getWorkingMinutes(parseTs(b.start), parseTs(ts)) : null,
          totalPausedMs: 0,
          pausedAt: null,
          isUrgent: !!b.urgent,
          status: ts ? 'completed' : 'in-progress',
          source: 'mail-auto',
        });
      });

      if (!newlyApplied.length) return;
      safeStorage.setItem('pbk_kitting_data', JSON.stringify(finalK));
      safeStorage.setItem('pbk_pick_cycles', JSON.stringify(mergedP));
      safeStorage.setItem('pbk_mail_applied', JSON.stringify([...applied, ...newlyApplied].slice(-4000)));
      setKittingData(finalK);
      setPickCycles(mergedP);
      console.log(`[MailAuto] 메일 자동 반영 — 신규 ${addedK}건, 완료 ${doneK}건`);
      if (addedK || doneK) showToast(`📨 메일 자동 반영 — 신규 ${addedK}건 / 완료 ${doneK}건`, 'success');
    } catch (e) { console.log('[MailAuto] skip:', e.message); }
  };

  // 아웃룩 메일(오더 CSV + [Kitting 완료])에서 복원한 과거 실적을 병합한다.
  // - 기존 레코드: 수량·오더발행일·자재담당 보강 + 실제 완료시각으로 리드타임 재계산
  // - 없는 오더: 키팅 현황 + 불출 Cycle 레코드를 새로 생성
  // React 상태가 아니라 localStorage 스냅샷을 기준으로 병합한 뒤 저장까지 직접 한다.
  // (초기 로드/동기화의 setState 와 경쟁해서 결과가 덮이는 것을 막기 위함)
  // 오더번호가 '1436073.0' 처럼 소수점째로 들어간 유령 레코드를 정리한다.
  // (엑셀에서 숫자로 저장된 CSV 때문에 같은 오더가 두 건으로 들어가 있었음)
  // 정상 번호가 이미 있으면 소수점 건을 버리고, 없으면 번호만 정정한다.
  const dedupeGhostOrders = (arr) => {
    if (!Array.isArray(arr) || !arr.length) return arr;
    const clean = new Set(arr.map(r => String((r && r.productionOrder) || '')).filter(o => o && !/\.\d+$/.test(o)));
    let changed = false;
    const kept = arr.filter(r => {
      const m = String((r && r.productionOrder) || '').match(/^(\d+)\.\d+$/);
      if (!m) return true;
      changed = true;
      if (clean.has(m[1])) return false;
      r.productionOrder = m[1];
      return true;
    });
    return changed ? kept : arr;
  };

  // localStorage 에 이미 들어가 있는 유령 레코드 정리 (백필이 건너뛰는 날에도 동작)
  const cleanupGhostOrders = () => {
    // 오더번호 없는 불출 레코드(초기 샘플 PO-2026-00x)는 리드타임과 연결되지 않고
    // 사이클타임 평균만 왜곡시키므로 제거한다
    const pc = safeParse(safeStorage.getItem('pbk_pick_cycles'), []);
    if (Array.isArray(pc) && pc.length) {
      const real = pc.filter(r => r && String(r.productionOrder || '').trim());
      if (real.length !== pc.length) {
        safeStorage.setItem('pbk_pick_cycles', JSON.stringify(real));
        setPickCycles(real);
        console.log(`[Cleanup] 오더번호 없는 불출 레코드 ${pc.length - real.length}건 제거`);
      }
    }
    for (const key of ['pbk_kitting_data', 'pbk_pick_cycles']) {
      const arr = safeParse(safeStorage.getItem(key), []);
      const kept = dedupeGhostOrders(arr);
      if (kept !== arr) {
        safeStorage.setItem(key, JSON.stringify(kept));
        console.log(`[Cleanup] ${key} 소수점 오더 ${arr.length - kept.length}건 정리`);
        if (key === 'pbk_kitting_data') setKittingData(kept); else setPickCycles(kept);
      }
    }
  };

  const applyKittingBackfill = async () => {
    try {
      cleanupGhostOrders();
      // 이미 최신 버전을 적용했다면 하루에 한 번만 확인 (147KB 다운로드 절약)
      const lastChk = parseInt(safeStorage.getItem('pbk_backfill_chk') || '0');
      if (safeStorage.getItem('pbk_backfill_ver') && Date.now() - lastChk < 24 * 60 * 60 * 1000) return;
      safeStorage.setItem('pbk_backfill_chk', String(Date.now()));
      const resp = await fetch(`https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main/public/data/kitting_backfill.json?t=${Date.now()}`);
      if (!resp.ok) return;
      const doc = await resp.json();
      const map = (doc && doc.orders) || {};
      const ver = String((doc && doc.version) || 1);
      const orderKeys = Object.keys(map);
      if (!orderKeys.length) return;
      // 취소된 오더 — 백필 파일의 removed 목록에 있는 건은 키팅·불출에서 삭제한다
      const removed = new Set((doc && Array.isArray(doc.removed) ? doc.removed : []).map(String));
      // 동기화 복원(loadDashboardState) 과 업로드에서도 걸러내야 하므로 남겨 둔다.
      // (백필이 지워도 그 뒤에 동기화가 원격 값을 다시 합쳐 넣어 되살아났음)
      safeStorage.setItem('pbk_removed_orders', JSON.stringify([...removed]));
      if (safeStorage.getItem('pbk_backfill_ver') === ver) return;   // 이미 적용됨

      const krDate = (iso) => new Date(iso).toLocaleDateString('ko-KR', { timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\. /g, '-').replace('.', '');

      // ── 키팅 현황
      const curKAll = safeParse(safeStorage.getItem('pbk_kitting_data'), []);
      const curK = removed.size ? curKAll.filter(k => !removed.has(String(k.productionOrder))) : curKAll;
      const removedK = curKAll.length - curK.length;
      const seenK = new Set(curK.map(k => String(k.productionOrder)));
      let updated = 0;
      const mergedK = curK.map(k => {
        const b = map[String(k.productionOrder)];
        if (!b) return k;
        const u = { ...k };
        // 손으로 고친 건(edited)은 사용자 값을 유지하고 빈 칸만 채운다.
        // 메일·SAP 이 정본이지만, 사람이 확인해서 넣은 값을 되돌리지는 않는다.
        const blank = (v) => v === undefined || v === null || v === '';
        const put = (field, val) => {
          if (val === undefined || val === null || val === '') return;
          if (k.edited && !blank(u[field])) return;
          u[field] = val;
        };
        put('qty', b.q);
        put('createdOn', b.created);
        put('warehousePic', b.pic);
        put('basicFinishDate', b.finish);
        // 접수시각·품번 등은 정본으로 덮어쓴다. (!u.startedAt 조건을 두면
        //  이전 버전의 잘못된 접수시각이 그대로 남는다)
        if (b.start && !b.startBad) put('startedAt', b.start);
        put('materialNum', b.mat);
        put('materialDesc', b.desc);
        if (b.mat) put('model', modelFromMaterial(b.mat));
        put('worker', b.sup);
        u.incomplete = b.incomplete ? 1 : undefined;
        if (b.done) {
          // 손으로 고친 건은 완료일이 정본과 같을 때만(=사람이 확인한 결과와 일치)
          // 분 단위 시각을 채워 준다. 날짜가 다르면 사용자 값을 그대로 둔다.
          const applyDone = !k.edited || blank(u.completedAt) || u.completedAt === krDate(b.done);
          if (applyDone) {
            u.completedAt = krDate(b.done);
            u.completedTs = b.done;
            u.status = 'completed';
            const st = (b.start && !b.startBad) ? b.start : u.startedAt;
            // 시작이 완료보다 늦은(신뢰 불가) 경우엔 리드타임을 비워 둔다
            if (st && parseTs(st) < parseTs(b.done)) u.leadTimeDays = getLeadTimeDays(parseTs(st), parseTs(b.done));
            else u.leadTimeDays = null;
          }
        }
        u.source = u.source || 'mail-backfill';
        updated++;
        return u;
      });
      let created = 0;
      orderKeys.forEach(o => {
        if (seenK.has(o)) return;
        const b = map[o];
        mergedK.push({
          id: 'bf-' + o,
          productionOrder: o,
          model: modelFromMaterial(b.mat),
          materialNum: b.mat || '',
          materialDesc: b.desc || '',
          qty: b.q != null ? b.q : null,
          createdOn: b.created || '',
          basicStartDate: b.created || '',
          basicFinishDate: b.finish || '',
          worker: b.sup || '',
          warehousePic: b.pic || '',
          incomplete: b.incomplete ? 1 : undefined,   // CSV 미수신 → 품번·수량·담당 미상
          isUrgent: false,
          status: b.done ? 'completed' : 'waiting',
          startedAt: (b.start && !b.startBad) ? b.start : null,
          completedAt: b.done ? krDate(b.done) : null,
          completedTs: b.done || null,
          leadTimeDays: (b.start && b.done && !b.startBad) ? getLeadTimeDays(parseTs(b.start), parseTs(b.done)) : null,
          createdAt: b.start || null,
          source: 'mail-backfill',
        });
        created++;
      });

      // ── 불출 Cycle (완료시각이 있는 오더만)
      const curPAll = safeParse(safeStorage.getItem('pbk_pick_cycles'), []);
      const curP = removed.size ? curPAll.filter(x => !removed.has(String(x.productionOrder))) : curPAll;
      const removedP = curPAll.length - curP.length;
      const seenP = new Set(curP.map(x => String(x.productionOrder || x.orderId)));
      // 기존 불출 레코드도 메일 기준으로 맞춘다. 그러지 않으면 같은 오더인데도
      // 키팅 L/T 의 완료시각(메일)과 불출 Cycle 의 완료시각(예전 클릭값)이 달라진다.
      let updatedP = 0;
      const mergedP = curP.map(x => {
        const b = map[String(x.productionOrder || '')];
        if (!b || x.edited) return x;
        const u = { ...x };
        if (b.mat) { u.materialNum = b.mat; u.model = modelFromMaterial(b.mat); }
        if (b.desc) u.materialDesc = b.desc;
        if (b.q != null) u.qty = b.q;
        if (b.sup) u.worker = b.sup;
        if (b.pic) u.warehousePic = b.pic;
        if (b.start && !b.startBad) { u.received = b.start; u.startTime = b.start; }
        if (b.done) { u.completed = b.done; u.status = 'completed'; }
        const st = u.startTime || u.received;
        if (st && u.completed) u.cycleMin = getWorkingMinutes(parseTs(st), parseTs(u.completed));
        u.totalPausedMs = 0;
        u.pausedAt = null;
        updatedP++;
        return u;
      });
      let createdP = 0;
      orderKeys.forEach(o => {
        if (seenP.has(o)) return;
        const b = map[o];
        if (!b.done || !b.start || b.startBad) return;
        mergedP.push({
          id: 'bf-p-' + o,
          productionOrder: o,
          model: modelFromMaterial(b.mat),
          materialNum: b.mat || '',
          materialDesc: b.desc || '',
          qty: b.q != null ? b.q : null,
          basicStartDate: b.created || '',
          worker: b.sup || '',
          warehousePic: b.pic || '',
          received: b.start,
          startTime: b.start,
          completed: b.done,
          cycleMin: getWorkingMinutes(parseTs(b.start), parseTs(b.done)),
          totalPausedMs: 0,
          pausedAt: null,
          isUrgent: false,
          status: 'completed',
          source: 'mail-backfill',
        });
        createdP++;
      });

      // 저장 먼저, 그 다음 상태 반영 (경쟁 시에도 localStorage 는 보존됨)
      const cleanK = dedupeGhostOrders(mergedK);
      const cleanP = dedupeGhostOrders(mergedP);
      safeStorage.setItem('pbk_kitting_data', JSON.stringify(cleanK));
      safeStorage.setItem('pbk_pick_cycles', JSON.stringify(cleanP));
      safeStorage.setItem('pbk_backfill_ver', ver);
      setKittingData(cleanK);
      setPickCycles(cleanP);
      console.log(`[Backfill] 메일 복원 적용 — 키팅 보강 ${updated}건/신규 ${created}건, 불출 보강 ${updatedP}건/신규 ${createdP}건, 취소 오더 삭제 ${removedK + removedP}건 (총 키팅 ${cleanK.length}, 불출 ${cleanP.length})`);
      showToast(`📥 과거 실적 복원 — 보강 ${updated}건 / 신규 ${created}건`, 'success');
    } catch (e) { console.log('[Backfill] skip:', e.message); }
  };

  // SAP_Drop 에 넣은 MB51 을 sap_watcher 가 집계해 둔 kpi_auto.json 을 반영한다.
  //   Movement 101/102 → GR Cancel (건수)
  //   Movement 711/712 → 재고조정 차이금액
  // 월말 재고금액(MB5B)은 아직 수동이라, 재고금액이 있는 달만 비율을 다시 계산한다.
  const applyKpiAuto = async () => {
    try {
      // 받아온 문서는 캐시해 두고 병합은 매번 다시 한다 (멱등이라 여러 번 해도 안전).
      // 동기화 복원 뒤에도 다시 얹어야 하므로 버전 가드를 두지 않는다.
      let doc = kpiAutoDocRef.current;
      if (!doc) {
        const resp = await fetch(`https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main/public/data/kpi_auto.json?t=${Date.now()}`);
        if (!resp.ok) return;
        doc = await resp.json();
        kpiAutoDocRef.current = doc;
      }
      const stamp = String(doc.updated || '');
      if (!stamp) return;

      const grQty = doc.grQty || {};
      const grCancel = doc.grCancel || {};
      const variance = doc.variance || {};
      const stock = doc.stock || {};
      const reasons = doc.reasons || {};
      if (!Object.keys(grQty).length && !Object.keys(variance).length && !Object.keys(stock).length) return;

      setKpiData(prev => {
        const next = {
          grCancel: { ...prev.grCancel, ...grCancel },
          grCancelQty: { ...prev.grCancelQty, ...grQty },
          inventoryAdjust: { ...prev.inventoryAdjust },
          invAdjustDetail: { ...prev.invAdjustDetail },
          adjustReasons: { ...(prev.adjustReasons || {}), ...reasons },
        };
        // MB5B 월말 재고금액
        Object.entries(stock).forEach(([m, v]) => {
          const cur = next.invAdjustDetail[m] || { stock: 0, variance: 0, ratioQ: 0, ratioCum: 0 };
          next.invAdjustDetail[m] = { ...cur, stock: v };
        });
        // MB51 711/712 차이금액
        Object.entries(variance).forEach(([m, amt]) => {
          const cur = next.invAdjustDetail[m] || { stock: 0, variance: 0, ratioQ: 0, ratioCum: 0 };
          next.invAdjustDetail[m] = { ...cur, variance: amt };
        });
        // 재고금액이 있는 달만 비율 재계산 (연 누적은 그 해 합계 기준)
        const years = new Set(Object.keys(next.invAdjustDetail).map(m => m.slice(0, 4)));
        years.forEach(y => {
          let sumVar = 0, sumStock = 0;
          Object.keys(next.invAdjustDetail).filter(m => m.startsWith(y)).sort().forEach(m => {
            const d = next.invAdjustDetail[m];
            if (!d.stock) return;
            sumVar += d.variance || 0;
            sumStock += d.stock;
            const q = parseFloat((d.variance / d.stock * 100).toFixed(4));
            const cum = parseFloat((sumVar / sumStock * 100).toFixed(4));
            next.invAdjustDetail[m] = { ...d, ratioQ: q, ratioCum: cum };
            next.inventoryAdjust[m] = q;
          });
        });
        safeStorage.setItem('pbk_kpi_data', JSON.stringify(next));
        return next;
      });
      const firstTime = safeStorage.getItem('pbk_kpiauto_ver') !== stamp;
      safeStorage.setItem('pbk_kpiauto_ver', stamp);
      safeStorage.setItem('pbk_sync_local_ts', Date.now().toString());
      const gr = Object.values(grQty).reduce((a, b) => a + b, 0);
      const cn = Object.values(grCancel).reduce((a, b) => a + b, 0);
      console.log(`[KPI Auto] 반영 — GR ${gr}건 / 취소 ${cn}건 / 재고조정 ${Object.keys(variance).length}개월 / 월말재고 ${Object.keys(stock).length}개월`);
      const parts = [];
      if (gr || cn) parts.push(`GR ${gr}건·취소 ${cn}건`);
      if (Object.keys(stock).length) parts.push(`월말재고 ${Object.keys(stock).length}개월`);
      if (Object.keys(variance).length) parts.push(`재고조정 ${Object.keys(variance).length}개월`);
      if (parts.length && firstTime) showToast(`📊 KPI 자동 반영 — ${parts.join(' / ')}`, 'success');
    } catch (e) { console.log('[KPI Auto] skip:', e.message); }
  };

  // 자재 → 협력업체 매핑을 받아 둔다. 하루 한 번만 확인한다.
  const loadSupplierMap = async () => {
    try {
      const lastChk = parseInt(safeStorage.getItem('pbk_supmap_chk') || '0');
      if (safeStorage.getItem('pbk_supplier_map') && Date.now() - lastChk < 24 * 60 * 60 * 1000) return;
      safeStorage.setItem('pbk_supmap_chk', String(Date.now()));
      const resp = await fetch(`https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main/public/data/supplier_map.json?t=${Date.now()}`);
      if (!resp.ok) return;
      const doc = await resp.json();
      if (!doc || !doc.materials || !Object.keys(doc.materials).length) return;
      const next = { materials: doc.materials, names: doc.names || {}, updated: doc.updated };
      safeStorage.setItem('pbk_supplier_map', JSON.stringify(next));
      setSupplierMap(next);
      console.log(`[Supplier] 업체 매핑 ${Object.keys(doc.materials).length}품번 / ${Object.keys(doc.names || {}).length}업체`);
    } catch (e) { console.log('[Supplier] skip:', e.message); }
  };

  // 재고 자재의 업체 구분 — 'all' / 업체코드 / 'inhouse'(사내제작) / 'none'(미확인)
  const supplierOf = (material) => {
    const m = String(material || '').trim();
    const code = supplierMap.materials?.[m];
    if (code) return code;
    return /^(KB|SP|AS|A2)/i.test(m) ? 'inhouse' : 'none';
  };
  const supplierLabel = (code) =>
    code === 'inhouse' ? '사내제작' : code === 'none' ? '미확인'
    : (supplierMap.names?.[code] || code);

  // kitting_scan.json의 start/end 이벤트를 Kitting 현황 + 불출 Cycle에 반영.
  // 적용한 이벤트 id는 pbk_scan_applied에 기록 (멱등). 주문이 아직 없는 이벤트는
  // 미적용으로 남겨서 CSV가 나중에 업로드되면 다음 주기에 자동 병합된다.
  const applyKittingScanEvents = async () => {
    try {
      const resp = await fetch(`https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main/public/data/kitting_scan.json?t=${Date.now()}`);
      if (!resp.ok) return;
      const json = await resp.json();
      const events = (json && Array.isArray(json.events)) ? json.events : [];
      if (!events.length) return;

      const applied = new Set(safeParse(safeStorage.getItem('pbk_scan_applied'), []));
      const currentKitting = safeParse(safeStorage.getItem('pbk_kitting_data'), []);
      const orderSet = new Set(currentKitting.map(k => String(k.productionOrder)));
      const applicable = events.filter(e => e && e.id && !applied.has(e.id) && orderSet.has(String(e.order)));
      if (!applicable.length) return;

      // 주문별 start/end 정리 (같은 주문에 여러 이벤트면 마지막 것 사용)
      const byOrder = {};
      applicable.forEach(e => {
        if (!byOrder[e.order]) byOrder[e.order] = {};
        byOrder[e.order][e.type] = e;
      });

      setKittingData(prev => prev.map(k => {
        const ev = byOrder[k.productionOrder];
        if (!ev || k.status === 'completed') return k;
        let u = k;
        if (ev.start) {
          u = { ...u, startedAt: ev.start.at, status: u.status === 'waiting' ? 'in-progress' : u.status };
        }
        if (ev.end) {
          const endDate = new Date(ev.end.at);
          const startRef = (ev.start && ev.start.at) || u.startedAt;
          u = {
            ...u,
            status: 'completed',
            completedAt: endDate.toLocaleDateString('ko-KR', { timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\. /g, '-').replace('.', ''),
            leadTimeDays: startRef ? getLeadTimeDays(new Date(startRef), endDate) : 0,
          };
        }
        return u;
      }));

      // 완료 이벤트 → 불출 Cycle도 완료 처리 (completeKitting과 동일 규칙)
      setPickCycles(prev => prev.map(p => {
        const key = p.productionOrder || p.orderId;
        const ev = byOrder[key];
        if (ev && ev.end && p.status !== 'completed') {
          const cycleMin = p.startTime ? calculateWorkingMinutes(p.startTime, ev.end.at) : 0;
          return { ...p, completed: ev.end.at.slice(0, 16).replace('T', ' '), cycleMin, status: 'completed' };
        }
        return p;
      }));

      const newApplied = [...applied, ...applicable.map(e => e.id)].slice(-2000);
      safeStorage.setItem('pbk_scan_applied', JSON.stringify(newApplied));
      const startCnt = applicable.filter(e => e.type === 'start').length;
      const endCnt = applicable.filter(e => e.type === 'end').length;
      console.log(`[KitScan] 폰 스캔 이벤트 병합: 시작 ${startCnt}건, 완료 ${endCnt}건`);
      showToast(`📱 폰 스캔 반영 — 시작 ${startCnt}건, 완료 ${endCnt}건`, 'success');
    } catch (e) { console.log('[KitScan] merge skip:', e.message); }
  };

  // ──── Dashboard State GitHub 동기화 ────

  // GitHub에서 dashboard_state.json 로드 → localStorage + React state 업데이트
  // force=true: 가드(마스터/타임스탬프) 무시하고 중앙 백업을 강제 적용 — "중앙 백업에서 복원" 버튼용
  const loadDashboardState = async (force = false) => {
    // 마스터 PC는 GitHub에서 로드하지 않음 (로컬 SAP 데이터가 항상 최신)
    const isMaster = safeStorage.getItem('pbk_sync_master') === 'true';
    if (isMaster && !force) {
      console.log('[DashSync] Master PC: skip GitHub load (local data is source of truth)');
      return;
    }

    const TOKEN = safeStorage.getItem('pbk_gh_token');
    const BASE = 'https://raw.githubusercontent.com/wjdwlals9545-arch/pbk-warehouse/main';
    try {
      // 항상 GitHub API 사용 (public repo는 토큰 없이도 가능, CDN 캐시 없음)
      const url = `https://api.github.com/repos/wjdwlals9545-arch/pbk-warehouse/contents/${DASHBOARD_STATE_PATH}`;
      const headers = TOKEN
        ? { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json' }
        : { Accept: 'application/vnd.github+json' };
      const resp = await fetch(url, { headers });
      if (!resp.ok) { console.log('[DashSync] No dashboard_state.json yet'); return; }

      const info = await resp.json();
      syncShaRef.current = info.sha;
      const decoded = decodeURIComponent(escape(atob(info.content.replace(/\n/g, ''))));
      const stateObj = JSON.parse(decoded);

      console.log('[DashSync] Loaded from GitHub, keys:', Object.keys(stateObj).length);

      // GitHub를 중앙 저장소로 사용 — 항상 GitHub 데이터를 신뢰
      const remoteTs = stateObj._syncTimestamp || 0;
      console.log(`[DashSync] GitHub 데이터 로드 (remoteTs=${remoteTs})`);

      // Excel 파생 데이터: 로컬에서 직접 파싱한 Excel이 원격 상태보다 최신이면 덮어쓰지 않음
      // (마스터 PC가 멈춰 dashboard_state.json이 오래된 경우, 5분 동기화가 최신 데이터를 롤백하는 것 방지)
      const EXCEL_KEYS = new Set([
        'pbk_inventory', 'pbk_last_updated',
        'pbk_open_po', 'pbk_open_po_raw', 'pbk_open_po_updated',
        'pbk_delivery_data', 'pbk_delivery_updated',
        'pbk_stock_epoch', 'pbk_po_epoch', 'pbk_del_epoch',
        'pbk_qstock',
      ]);
      const localExcelEpoch = Math.max(
        parseInt(safeStorage.getItem('pbk_stock_epoch') || '0'),
        parseInt(safeStorage.getItem('pbk_po_epoch') || '0'),
        parseInt(safeStorage.getItem('pbk_del_epoch') || '0')
      );
      const skipExcelKeys = !force && localExcelEpoch > remoteTs;
      if (skipExcelKeys) console.log(`[DashSync] 로컬 Excel 데이터가 더 최신 (${localExcelEpoch} > ${remoteTs}) → Excel 키 건너뜀`);

      // 사용자 입력 데이터(투두/키팅/KPI 등): 이 PC의 마지막 편집이 원격 스냅샷보다 최신이면 덮어쓰지 않음
      // (마스터 PC가 멈춰 원격 상태가 오래된 경우, 5분 동기화가 최근 입력을 롤백하는 것 방지)
      // 추가 안전장치: pbk_sync_local_ts가 저장 실패(쿼터 초과 등)로 없더라도,
      // 로컬 Excel이 원격 스냅샷보다 최신이면 그 스냅샷은 낡은 것이므로 사용자 키도 덮어쓰지 않음
      const localEditTs = parseInt(safeStorage.getItem('pbk_sync_local_ts') || '0');
      const skipUserKeys = !force && (localEditTs > remoteTs || localExcelEpoch > remoteTs);
      if (skipUserKeys) console.log(`[DashSync] 로컬이 더 최신 (edit=${localEditTs}, excel=${localExcelEpoch} vs remote=${remoteTs}) → 사용자 입력 키 건너뜀`);

      // setState 매핑
      const setterMap = {
        pbk_receive_cycles: setReceiveCycles,
        pbk_pick_cycles: setPickCycles,
        pbk_kitting_data: setKittingData,
        pbk_todo_list: setTodoList,
        pbk_kpi_data: (val) => setKpiData({
          grCancel: { ...DEFAULT_GR_CANCEL_DATA, ...(val.grCancel || {}) },
          grCancelQty: { ...DEFAULT_GR_CANCEL_QTY, ...(val.grCancelQty || {}) },
          inventoryAdjust: val.inventoryAdjust || {},
          invAdjustDetail: val.invAdjustDetail || {},
          adjustReasons: val.adjustReasons || {}
        }),
        pbk_temp_humidity_data: (val) => setTempHumidityData(prev => ({ ...HISTORICAL_TEMP_HUMIDITY_DATA, ...prev, ...val })),
        pbk_temp_humidity_recorder: setTempHumidityRecorder,
        pbk_weight_data: setWeightData,
        pbk_custom_bom: setCustomBomData,
        pbk_subcom_bom: setSubComponentBomData,
        pbk_bom_updated: setBomLastUpdated,
        pbk_notifications: setNotifications,
        pbk_previous_stats: setPreviousStats,
        // v19.8: Stock, Open PO, Delivery
        pbk_inventory: setInventoryData,
        pbk_last_updated: setLastUpdated,
        pbk_open_po: setOpenPOData,
        pbk_open_po_raw: setOpenPORawItems,
        pbk_open_po_updated: setOpenPOLastUpdated,
        pbk_delivery_data: setDeliveryData,
        pbk_delivery_updated: (val) => { safeStorage.setItem('pbk_delivery_updated', val); setDeliveryLastUpdated(val); },
        pbk_qstock: setQStockData,
        pbk_last_auto_backup: setLastAutoBackup,
      };

      for (const key of SYNC_KEYS) {
        if (skipExcelKeys && EXCEL_KEYS.has(key)) continue;
        if (skipUserKeys && !EXCEL_KEYS.has(key)) continue;
        if (stateObj[key] !== undefined && stateObj[key] !== null) {
          // localStorage 업데이트
          let val = stateObj[key];
          // 키팅/불출은 덮어쓰지 않고 합친다. 메일로 복원한 과거 실적은 백업 파일에서
          // 제외돼 있어(kitting_backfill.json 이 정본), 그대로 덮으면 718건이 사라진다.
          if ((key === 'pbk_kitting_data' || key === 'pbk_pick_cycles') && Array.isArray(val)) {
            const local = safeParse(safeStorage.getItem(key), []);
            if (Array.isArray(local) && local.length) {
              const remoteOrders = new Set(val.map(r => String((r && r.productionOrder) || '')));
              const extra = local.filter(r => r && !remoteOrders.has(String(r.productionOrder || '')));
              if (extra.length) val = val.concat(extra);
            }
            // 취소된 오더는 원격에 남아 있어도 되살리지 않는다
            const gone = new Set(safeParse(safeStorage.getItem('pbk_removed_orders'), []).map(String));
            if (gone.size) val = val.filter(r => !gone.has(String((r && r.productionOrder) || '')));
          }
          safeStorage.setItem(key, typeof val === 'string' ? val : JSON.stringify(val));
          // React state 업데이트
          if (setterMap[key]) {
            setterMap[key](val);
          }
        }
      }

      // 로드 후 현재 해시 저장 (불필요한 업로드 방지)
      lastSyncHashRef.current = simpleHash(JSON.stringify(stateObj));
      console.log('[DashSync] 대시보드 데이터 동기화 완료');
      if (force) showToast('☁️ 중앙 백업에서 복원 완료 — 키팅/투두/KPI 등 사용자 데이터를 백업 시점으로 되돌렸습니다', 'success');
    } catch (err) {
      console.log('[DashSync] Load error:', err.message);
    }
  };

  // 현재 상태를 dashboard_state.json으로 GitHub에 업로드 (마스터 PC만)
  const uploadDashboardState = async () => {
    const TOKEN = safeStorage.getItem('pbk_gh_token');
    if (!TOKEN) return;

    // 마스터 PC만 업로드 가능 (SAP 추출 PC)
    // 설정: localStorage.setItem('pbk_sync_master', 'true')
    const isMaster = safeStorage.getItem('pbk_sync_master') === 'true';
    if (!isMaster) {
      console.log('[DashSync] Read-only mode (not master PC), skip upload');
      return;
    }

    // 좀비 마스터 가드: 이 PC에서 실제 편집한 적이 없으면(pbk_sync_local_ts 없음) 업로드 금지
    // (오래 꺼져 있던 옛 마스터 PC가 켜지자마자 낡은 상태로 전체를 덮어쓰는 사고 방지)
    const localEditTs = parseInt(safeStorage.getItem('pbk_sync_local_ts') || '0');
    if (!localEditTs) {
      console.log('[DashSync] 이 PC의 편집 이력 없음 → 업로드 건너뜀 (좀비 마스터 가드)');
      return;
    }

    // 현재 상태 수집
    const stateObj = {};
    for (const key of SYNC_KEYS) {
      const raw = safeStorage.getItem(key);
      if (raw !== null) {
        try { stateObj[key] = JSON.parse(raw); } catch { stateObj[key] = raw; }
      }
    }
    // 메일에서 복원한 과거 실적은 kitting_backfill.json 에 이미 있으므로 백업에서 제외한다.
    // (넣으면 동기화 파일이 3배로 커져 로딩·업로드가 느려짐. 손으로 고친 건(edited)은 유지)
    const goneOrders = new Set(safeParse(safeStorage.getItem('pbk_removed_orders'), []).map(String));
    for (const key of ['pbk_kitting_data', 'pbk_pick_cycles']) {
      if (Array.isArray(stateObj[key])) {
        stateObj[key] = stateObj[key].filter(r =>
          !(r && r.source === 'mail-backfill' && !r.edited) &&
          !(r && goneOrders.has(String(r.productionOrder || ''))));
      }
    }
    // 타임스탬프 포함 (로컬 vs 리모트 비교용)
    stateObj._syncTimestamp = Date.now();

    // 변경 감지
    const currentHash = simpleHash(JSON.stringify(stateObj));
    if (currentHash === lastSyncHashRef.current) {
      console.log('[DashSync] No changes, skip upload');
      return;
    }

    const OWNER = 'wjdwlals9545-arch';
    const REPO = 'pbk-warehouse';
    const API = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${DASHBOARD_STATE_PATH}`;
    const jsonStr = JSON.stringify(stateObj, null, 0);
    const content = btoa(unescape(encodeURIComponent(jsonStr)));

    const doUpload = async (sha) => {
      const body = { message: 'Sync dashboard state', content, ...(sha ? { sha } : {}) };
      return fetch(API, {
        method: 'PUT',
        headers: { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
    };

    try {
      // 원격 상태 조회 (SHA + 데이터 급감 방어용 내용 비교)
      let remoteState = null;
      try {
        const getResp = await fetch(API, {
          headers: { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json' }
        });
        if (getResp.ok) {
          const info = await getResp.json();
          syncShaRef.current = info.sha;
          try {
            remoteState = JSON.parse(decodeURIComponent(escape(atob(info.content.replace(/\n/g, '')))));
          } catch { /* 내용 파싱 실패 시 방어 생략 */ }
        }
      } catch { /* 새 파일 */ }

      // ⚠️ 데이터 급감 방어: 중앙 백업에 있는 사용자 데이터가 로컬보다 현저히 많으면 업로드 중단.
      // (복원 전 상태의 마스터 PC가 빈 데이터로 중앙 백업을 날리는 사고 방지 — 2026-07-08 사건의 역방향)
      if (remoteState) {
        const GUARD_KEYS = ['pbk_kitting_data', 'pbk_pick_cycles', 'pbk_receive_cycles', 'pbk_todo_list'];
        const shrunk = GUARD_KEYS.filter(k => {
          const rc = Array.isArray(remoteState[k]) ? remoteState[k].length : 0;
          const lc = Array.isArray(stateObj[k]) ? stateObj[k].length : 0;
          return rc >= 5 && lc < rc * 0.5; // 원격 5건 이상인데 로컬이 절반 미만
        });
        if (shrunk.length > 0) {
          const detail = shrunk.map(k => `${k}: 로컬 ${(stateObj[k] || []).length} vs 백업 ${remoteState[k].length}`).join(', ');
          console.warn('[DashSync] 데이터 급감 감지 → 업로드 차단:', detail);
          showToast(`🛡️ 업로드 차단 — 중앙 백업보다 데이터가 적습니다 (${detail}). Data Mgmt에서 "복원 실행" 먼저 하세요.`, 'error');
          return;
        }
      }

      let resp = await doUpload(syncShaRef.current);

      // 409 충돌 → SHA 재조회 후 재시도
      if (resp.status === 409) {
        console.log('[DashSync] SHA conflict, retrying...');
        const getResp = await fetch(API, {
          headers: { Authorization: `token ${TOKEN}`, Accept: 'application/vnd.github+json' }
        });
        if (getResp.ok) {
          const info = await getResp.json();
          syncShaRef.current = info.sha;
        }
        resp = await doUpload(syncShaRef.current);
      }

      if (resp.ok) {
        const result = await resp.json();
        syncShaRef.current = result.content.sha;
        lastSyncHashRef.current = currentHash;
        console.log('[DashSync] Upload OK');
      } else {
        console.error('[DashSync] Upload failed:', resp.status);
      }
    } catch (err) {
      console.error('[DashSync] Upload error:', err.message);
    }
  };

  // 3D 뷰 렌더링
  const view3dKeyRef = React.useRef(null);
  useEffect(() => {
    if(activeTab !== 'view3d' || !layoutData || !view3dCanvasRef.current || isMobileDevice) return;
    if(view3dSceneRef.current) { view3dSceneRef.current.renderer.dispose(); view3dSceneRef.current = null; }
    if(view3dKeyRef.current) { if(view3dKeyRef.current.down){window.removeEventListener('keydown',view3dKeyRef.current.down);window.removeEventListener('keyup',view3dKeyRef.current.up);}else{window.removeEventListener('keydown',view3dKeyRef.current);}view3dKeyRef.current=null; }
    const loadAndInit = () => {
      const THREE = window.THREE;
      if(!THREE) return;
      const cv = view3dCanvasRef.current;
      if(!cv) return;
      const W = cv.clientWidth || 800, H = cv.clientHeight || 600;
      const S3D = 0.06, BX3D = 50, BY3D = 50;
      const toM = (px) => px / S3D / 1000;
      // 시리즈 색상 — etc를 밝은 청록색으로
      const SERIES_COLORS = {mx48:0xdc2626,mx16:0x2563eb,hsm:0xd97706,semi:0xeab308,spare:0x7c3aed,etc:0x06b6d4};
      const rpx3d = (r) => {
        var w,h;
        if(r.t==='custom'){w=(r.cw||1000)*S3D;h=(r.ch||500)*S3D;}
        else{w=(r.t==='heavy'?1800:900)*S3D;h=450*S3D;}
        if(r.rot===true||r.rot===90||r.rot===270){var tmp=w;w=h;h=tmp;}
        return {w:w,h:h};
      };
      const scene = new THREE.Scene();
      scene.background = new THREE.Color(0x0f172a);
      const camera = new THREE.PerspectiveCamera(50, W/H, 0.1, 200);
      const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
      const renderer = new THREE.WebGLRenderer({canvas:cv, antialias:!isSafari, preserveDrawingBuffer:false, powerPreference:'high-performance'});
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(W, H); renderer.shadowMap.enabled = !isSafari;
      view3dSceneRef.current = {scene, camera, renderer};
      scene.add(new THREE.AmbientLight(0xffffff, 0.5));
      const dl = new THREE.DirectionalLight(0xffffff, 0.6);
      dl.position.set(20, 30, 10); dl.castShadow = true; scene.add(dl);

      // Floor (L-shape)
      const whw=toM(564),whh=toM(1890),jy=toM(774),rx=toM(982-BX3D);
      const floorShape = new THREE.Shape();
      floorShape.moveTo(0,0);floorShape.lineTo(whw,0);floorShape.lineTo(whw,jy);
      floorShape.lineTo(rx,jy);floorShape.lineTo(rx,whh);floorShape.lineTo(0,whh);
      const floor = new THREE.Mesh(new THREE.ShapeGeometry(floorShape), new THREE.MeshStandardMaterial({color:0x1a2332,side:THREE.DoubleSide}));
      floor.rotation.x = -Math.PI/2; floor.receiveShadow = true; scene.add(floor);

      // Walls
      const wallH = 3.5;
      const pts = [[0,0],[whw,0],[whw,jy],[rx,jy],[rx,whh],[0,whh]];
      for(let i=0;i<pts.length;i++){
        const p0=pts[i],p1=pts[(i+1)%pts.length];
        const dx=p1[0]-p0[0],dz=p1[1]-p0[1],len=Math.sqrt(dx*dx+dz*dz);
        const wall=new THREE.Mesh(new THREE.PlaneGeometry(len,wallH),new THREE.MeshStandardMaterial({color:0x475569,transparent:true,opacity:0.15,side:THREE.DoubleSide}));
        wall.position.set((p0[0]+p1[0])/2,wallH/2,(p0[1]+p1[1])/2);
        wall.rotation.y=-Math.atan2(dz,dx); scene.add(wall);
      }

      // 라벨: Sprite 방식 (항상 카메라를 향해 읽기 쉬움)
      function makeLabel(text,x,topY,z,scale,color){
        const cW=512,cH=64;
        const c=document.createElement('canvas');c.width=cW;c.height=cH;
        const ctx=c.getContext('2d');
        ctx.clearRect(0,0,cW,cH);
        var fontSize=32;
        ctx.font='bold '+fontSize+'px sans-serif';
        while(ctx.measureText(text).width>cW-10&&fontSize>8){fontSize-=2;ctx.font='bold '+fontSize+'px sans-serif';}
        ctx.fillStyle='rgba(0,0,0,0.6)';
        var tw=Math.min(ctx.measureText(text).width+16,cW);
        ctx.fillRect((cW-tw)/2,4,tw,cH-8);
        ctx.fillStyle=color||'#ffffff';
        ctx.textAlign='center';ctx.textBaseline='middle';
        ctx.fillText(text,cW/2,cH/2);
        const tex=new THREE.CanvasTexture(c);tex.minFilter=THREE.LinearFilter;
        const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,depthWrite:false,depthTest:false}));
        sp.position.set(x,topY+0.15,z);
        var s=scale||1.2;
        sp.scale.set(s,s*cH/cW,1);
        scene.add(sp);
      }

      // 랙 렌더링
      if(layoutData.R) layoutData.R.forEach(r => {
        const rp=rpx3d(r),wM=toM(rp.w),dM=toM(rp.h);
        const xM=toM(r.x-BX3D),zM=toM(r.y-BY3D);
        const nm=(r.a||'').toUpperCase();
        const isPillar=nm.indexOf('PILLAR')>=0||(r.a||'').indexOf('\uae30\ub465')>=0||(r.cc==='#6b7280')||(r.t==='custom'&&(r.cw||0)<=600&&(r.ch||0)<=600&&nm.indexOf('DOOR')<0&&nm.indexOf('PLT')<0);
        const isDoor=nm.indexOf('DOOR')>=0;
        const isPLT=nm.indexOf('PLT')>=0;
        // 높이
        var hM=1.8;// 기본 1.8m
        if(isDoor)hM=2.0;
        else if(isPLT)hM=0.3;
        else if(isPillar)hM=1.8;// 기둥
        // 색상
        var col=isDoor?0x10b981:isPillar?0x6b7280:isPLT?0xa16207:(SERIES_COLORS[r.s]||0x06b6d4);
        var op=isDoor?0.5:isPillar?0.95:isPLT?0.7:0.9;
        // DOOR: 얇은 프레임 (높이 2m, 깊이 0.05m)
        var geoW=wM,geoH=hM,geoD=dM;
        if(isDoor){geoD=Math.max(dM,0.05);geoW=Math.max(wM,0.05);}
        const mesh=new THREE.Mesh(new THREE.BoxGeometry(geoW,geoH,geoD),new THREE.MeshStandardMaterial({color:col,transparent:true,opacity:op}));
        mesh.position.set(xM+wM/2,geoH/2,zM+dM/2);mesh.castShadow=true;scene.add(mesh);
        // 엣지 (DOOR은 두껍게)
        const edgeLine=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(geoW,geoH,geoD)),new THREE.LineBasicMaterial({color:isDoor?0x34d399:isPillar?0x94a3b8:col,transparent:true,opacity:isDoor?0.8:0.4}));
        edgeLine.position.copy(mesh.position);scene.add(edgeLine);
        // 라벨
        var lblScale=Math.max(wM*1.5,1);
        makeLabel(r.a,xM+wM/2,geoH,zM+dM/2,lblScale,isPillar?'#94a3b8':isDoor?'#34d399':isPLT?'#fbbf24':'#ffffff');
      });

      // 존 — 이름별 높이/색상
      const ZONE_CFG={
        'Packaging Foam':{h:1.8,c:0x22c55e,op:0.6},
        'Spare Part Box':{h:1.8,c:0x22c55e,op:0.6},
        'Injection':{h:0.3,c:0x3b82f6,op:0.3},
        'Stand':{h:1.8,c:0xf59e0b,op:0.9},
        'Tablet':{h:1.8,c:0xf59e0b,op:0.9},
        'Base Plate':{h:0.5,c:0x8b5cf6,op:0.6},
        'Yellow Box':{h:0.8,c:0xeab308,op:0.6},
        '8160 Area':{h:3.5,c:0x94a3b8,op:0.5},
        'Barcode/ E6150 Area':{h:0.3,c:0x8b5cf6,op:0.5},
        'Defect Area':{h:0.01,c:0xef4444,op:0.2},
        'Test Area':{h:0.01,c:0x3b82f6,op:0.15},
        'Final QC Area':{h:0.01,c:0x3b82f6,op:0.15}
      };
      if(layoutData.zones) layoutData.zones.forEach(z => {
        const wM=toM(z.w),dM=toM(z.h),xM=toM(z.x),zM=toM(z.y);
        var cfg=ZONE_CFG[z.n];
        if(!cfg){
          // 이름에 '기둥' 포함 시 1.8m 기둥으로 처리
          if(z.n.indexOf('\uae30\ub465')>=0) cfg={h:1.8,c:0x6b7280,op:0.95};
          else cfg={h:0.3,c:0x22c55e,op:0.4};
        }
        const mesh=new THREE.Mesh(new THREE.BoxGeometry(wM,cfg.h,dM),new THREE.MeshStandardMaterial({color:cfg.c,transparent:true,opacity:cfg.op}));
        mesh.position.set(xM+wM/2,cfg.h/2,zM+dM/2); scene.add(mesh);
        if(cfg.h>=0.1){
          var lblScale=Math.max(wM,1.5);
          makeLabel(z.n,xM+wM/2,cfg.h,zM+dM/2,lblScale,'#ffffff');
        }
      });

      // Camera orbit + 화살표 키 이동
      let isDrag=false,prevX=0,prevY=0,theta=0.8,phi=0.5,dist=35;
      const target=new THREE.Vector3(whw/2,0,whh/3);
      const updateCam=()=>{camera.position.set(target.x+dist*Math.sin(theta)*Math.cos(phi),dist*Math.sin(phi),target.z+dist*Math.cos(theta)*Math.cos(phi));camera.lookAt(target);};
      updateCam();
      cv.addEventListener('mousedown',e=>{isDrag=true;prevX=e.clientX;prevY=e.clientY;});
      cv.addEventListener('mousemove',e=>{if(!isDrag)return;
        if(walkState.active){
          // 워크스루: 자키 방향 직접 회전
          walkState.angle-=(e.clientX-prevX)*0.005;
          walkState.camPhi=Math.max(0.1,Math.min(1.2,walkState.camPhi+(e.clientY-prevY)*0.005));
          prevX=e.clientX;prevY=e.clientY;
        } else {
          theta+=(e.clientX-prevX)*0.005;phi=Math.max(0.1,Math.min(1.5,phi+(e.clientY-prevY)*0.005));prevX=e.clientX;prevY=e.clientY;updateCam();
        }
      });
      window.addEventListener('mouseup',()=>{isDrag=false;});
      cv.addEventListener('wheel',e=>{
        if(walkState.active){
          walkState.camDist=Math.max(2,Math.min(12,walkState.camDist+e.deltaY*0.01));
        } else {
          dist=Math.max(5,Math.min(80,dist+e.deltaY*0.03));updateCam();
        }
        e.preventDefault();
      },{passive:false});

      const onKey=e=>{
        var kl=e.key.toLowerCase();
        // 워크스루 모드 키 처리
        if(walkState.active){
          if('wasdqe'.indexOf(kl)>=0){
            walkState.keys[kl]=true;e.preventDefault();return;
          }
          if(e.key==='Escape'){
            if(view3dCtrlRef.current)view3dCtrlRef.current.toggleWalk();
            var btn=document.getElementById('btn3dWalk');if(btn)btn.classList.remove('bg-yellow-700');
            e.preventDefault();return;
          }
          return;
        }
        // 오빗 모드: WASD + 화살표 모두 지원
        const sp=0.5;
        var fwdX=Math.sin(theta),fwdZ=Math.cos(theta);
        var rightX=Math.cos(theta),rightZ=-Math.sin(theta);
        if(kl==='a'||e.key==='ArrowLeft'){target.x-=rightX*sp;target.z-=rightZ*sp;updateCam();e.preventDefault();}
        else if(kl==='d'||e.key==='ArrowRight'){target.x+=rightX*sp;target.z+=rightZ*sp;updateCam();e.preventDefault();}
        else if(kl==='w'||e.key==='ArrowUp'){target.x-=fwdX*sp;target.z-=fwdZ*sp;updateCam();e.preventDefault();}
        else if(kl==='s'||e.key==='ArrowDown'){target.x+=fwdX*sp;target.z+=fwdZ*sp;updateCam();e.preventDefault();}
      };
      const onKeyUp=e=>{
        if(walkState.active){
          var kl=e.key.toLowerCase();
          if('wasdqe'.indexOf(kl)>=0){walkState.keys[kl]=false;e.preventDefault();}
        }
      };
      window.addEventListener('keydown',onKey);
      window.addEventListener('keyup',onKeyUp);
      view3dKeyRef.current = {down:onKey, up:onKeyUp};

      // ── 외부 제어 함수 노출 ──
      view3dCtrlRef.current = {
        setCamPreset: function(preset){
          if(view3dWalkRef.current&&view3dWalkRef.current.active) return;// 워크스루 중 프리셋 비활성
          if(preset==='top'){theta=0;phi=1.5;dist=30;target.set(whw/2,0,whh/2);}
          else if(preset==='front'){theta=0;phi=0.3;dist=35;target.set(whw/2,0,whh);}
          else if(preset==='entrance'){theta=0.3;phi=0.4;dist=25;target.set(whw/2,0,2);}
          else if(preset==='side'){theta=Math.PI/2;phi=0.4;dist=35;target.set(0,0,whh/2);}
          else if(preset==='iso'){theta=0.8;phi=0.5;dist=35;target.set(whw/2,0,whh/3);}
          updateCam();
        },

      };

      // ══════════════════════════════════════════════════
      // ██ 워크스루 시뮬레이션 (자키 + 파렛트 동선 검증) ██
      // ══════════════════════════════════════════════════

      // --- 충돌 박스 수집 (모든 랙, 존, 벽) ---
      var colliders = [];
      if(layoutData.R) layoutData.R.forEach(function(r){
        var nm=(r.a||'').toUpperCase();
        var rp=rpx3d(r),wM=toM(rp.w),dM=toM(rp.h);
        var xM=toM(r.x-BX3D),zM=toM(r.y-BY3D);
        // DOOR만 통과 가능(passable), PLT는 충돌 대상
        var pass=(nm.indexOf('DOOR')>=0);
        colliders.push({minX:xM,maxX:xM+wM,minZ:zM,maxZ:zM+dM,name:r.a||'rack',passable:pass});
      });
      if(layoutData.zones) layoutData.zones.forEach(function(z){
        var wM=toM(z.w),dM=toM(z.h),xM=toM(z.x),zM=toM(z.y);
        // 모든 배치된 존을 충돌 대상으로 등록
        colliders.push({minX:xM,maxX:xM+wM,minZ:zM,maxZ:zM+dM,name:z.n});
      });
      // 벽 충돌 (L자 건물 외곽 — 벗어나지 못하도록)
      var wallThick=0.05;
      // 하단벽(z=0), 우측벽(x=whw, z<jy), 상단벽z=jy(x>rx), 내벽x=rx(z>jy), 상단벽z=whh(x<rx), 좌측벽x=0
      colliders.push({minX:-wallThick,maxX:whw+wallThick,minZ:-wallThick-0.5,maxZ:-wallThick,name:'wall-bottom'});
      colliders.push({minX:whw,maxX:whw+wallThick,minZ:-wallThick,maxZ:jy+wallThick,name:'wall-right'});
      colliders.push({minX:rx,maxX:whw+wallThick,minZ:jy,maxZ:jy+wallThick,name:'wall-step-h'});
      colliders.push({minX:rx,maxX:rx+wallThick,minZ:jy,maxZ:whh+wallThick,name:'wall-step-v'});
      colliders.push({minX:-wallThick,maxX:rx+wallThick,minZ:whh,maxZ:whh+wallThick,name:'wall-top'});
      colliders.push({minX:-wallThick-0.5,maxX:-wallThick,minZ:-wallThick,maxZ:whh+wallThick,name:'wall-left'});

      // --- 자키 + 파렛트 3D 모델 생성 ---
      var jackGroup = new THREE.Group();
      jackGroup.visible = false;
      // 파렛트: 1100×1100mm, 높이 150mm
      var palletW=1.1, palletD=1.1, palletH=0.15;
      var palletMesh = new THREE.Mesh(
        new THREE.BoxGeometry(palletW,palletH,palletD),
        new THREE.MeshStandardMaterial({color:0xc4a035,roughness:0.8})
      );
      palletMesh.position.y=palletH/2;
      palletMesh.castShadow=true;
      jackGroup.add(palletMesh);
      // 파렛트 엣지
      var palletEdge=new THREE.LineSegments(
        new THREE.EdgesGeometry(new THREE.BoxGeometry(palletW,palletH,palletD)),
        new THREE.LineBasicMaterial({color:0x8b6914})
      );
      palletEdge.position.copy(palletMesh.position);
      jackGroup.add(palletEdge);
      // 핸드잭 포크 2개: 파렛트 아래에 들어감 (폭150mm×길이1000mm×높이50mm)
      var forkW=0.15, forkD=1.0, forkH=0.05;
      var forkMat=new THREE.MeshStandardMaterial({color:0x4a90d9,roughness:0.4,metalness:0.6});
      var forkL=new THREE.Mesh(new THREE.BoxGeometry(forkW,forkH,forkD),forkMat);
      forkL.position.set(-0.17,forkH/2,0.05);// 파렛트 아래 좌측
      jackGroup.add(forkL);
      var forkR=new THREE.Mesh(new THREE.BoxGeometry(forkW,forkH,forkD),forkMat);
      forkR.position.set(0.17,forkH/2,0.05);// 파렛트 아래 우측
      jackGroup.add(forkR);
      // 펌프 본체: 파렛트 뒤에 (폭450mm×길이300mm×높이200mm)
      var pumpW=0.45, pumpD=0.3, pumpH=0.2;
      var pumpMesh=new THREE.Mesh(
        new THREE.BoxGeometry(pumpW,pumpH,pumpD),
        new THREE.MeshStandardMaterial({color:0x3b78c4,roughness:0.3,metalness:0.7})
      );
      pumpMesh.position.set(0,pumpH/2,-palletD/2-pumpD/2);
      pumpMesh.castShadow=true;
      jackGroup.add(pumpMesh);
      // 핸들 (수직 봉 + 가로 손잡이)
      var handleMesh = new THREE.Mesh(
        new THREE.CylinderGeometry(0.02,0.02,0.8,8),
        new THREE.MeshStandardMaterial({color:0x666666,metalness:0.8})
      );
      handleMesh.position.set(0,0.5,-palletD/2-pumpD);
      jackGroup.add(handleMesh);
      // 핸들 가로 손잡이
      var handleGrip=new THREE.Mesh(
        new THREE.CylinderGeometry(0.015,0.015,0.35,8),
        new THREE.MeshStandardMaterial({color:0x444444,metalness:0.6})
      );
      handleGrip.rotation.z=Math.PI/2;
      handleGrip.position.set(0,0.9,-palletD/2-pumpD);
      jackGroup.add(handleGrip);
      // 충돌 바운딩 표시 (파렛트 + 뒤쪽 펌프만)
      var totalD=palletD+pumpD;// 1.1+0.3=1.4m
      var jackBoundVis = new THREE.Mesh(
        new THREE.BoxGeometry(palletW+0.05,0.02,totalD+0.05),
        new THREE.MeshBasicMaterial({color:0x00ff00,transparent:true,opacity:0.2,side:THREE.DoubleSide})
      );
      jackBoundVis.position.set(0,0.01,-pumpD/2);
      jackGroup.add(jackBoundVis);
      scene.add(jackGroup);

      // --- 클리어런스 측정 라인 (좌/우) ---
      var clearLineL = new THREE.Line(
        new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,0.3,0),new THREE.Vector3(-1,0.3,0)]),
        new THREE.LineBasicMaterial({color:0x00ff00,linewidth:2})
      );clearLineL.visible=false;scene.add(clearLineL);
      var clearLineR = new THREE.Line(
        new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,0.3,0),new THREE.Vector3(1,0.3,0)]),
        new THREE.LineBasicMaterial({color:0x00ff00,linewidth:2})
      );clearLineR.visible=false;scene.add(clearLineR);
      // 전방 클리어런스 라인
      var clearLineF = new THREE.Line(
        new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,0.3,0),new THREE.Vector3(0,0.3,1)]),
        new THREE.LineBasicMaterial({color:0x00ff00,linewidth:2})
      );clearLineF.visible=false;scene.add(clearLineF);

      // 3D 거리 라벨 함수
      function makeDynLabel(){
        var cW=256,cH=64;
        var c=document.createElement('canvas');c.width=cW;c.height=cH;
        var tex=new THREE.CanvasTexture(c);tex.minFilter=THREE.LinearFilter;
        var sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,depthWrite:false,depthTest:false,transparent:true}));
        sp.scale.set(1.2,0.3,1);sp.visible=false;
        scene.add(sp);
        return {sprite:sp,canvas:c,texture:tex};
      }
      var labelL=makeDynLabel(),labelR=makeDynLabel(),labelF=makeDynLabel();

      // --- 랙 근접 정보 표시 ---
      var SERIES_NAMES={mx48:'Maxwell48',mx16:'Maxwell16',hsm:'HSM',semi:'Semi Goods',spare:'Spare',etc:'E3/D2'};
      var SERIES_HEX={mx48:'#ef4444',mx16:'#3b82f6',hsm:'#d97706',semi:'#eab308',spare:'#7c3aed',etc:'#06b6d4'};
      // 랙 위치 데이터 (3D 좌표 + 메타)
      var rackInfos=[];
      if(layoutData.R) layoutData.R.forEach(function(r){
        var nm=(r.a||'').toUpperCase();
        if(nm.indexOf('DOOR')>=0||nm.indexOf('PILLAR')>=0||nm.indexOf('PLT')>=0||r.t==='custom') return;
        var rp=rpx3d(r),wM=toM(rp.w),dM=toM(rp.h);
        var xM=toM(r.x-BX3D)+wM/2,zM=toM(r.y-BY3D)+dM/2;
        rackInfos.push({x:xM,z:zM,name:r.a||'',series:r.s||'etc',bins:r.b||0});
      });
      // 근접 랙 라벨 (최대 3개)
      var rackLabels=[];
      for(var ri=0;ri<3;ri++){
        var rlc=document.createElement('canvas');rlc.width=512;rlc.height=64;
        var rlTex=new THREE.CanvasTexture(rlc);rlTex.minFilter=THREE.LinearFilter;
        var rlSp=new THREE.Sprite(new THREE.SpriteMaterial({map:rlTex,depthWrite:false,depthTest:false,transparent:true}));
        rlSp.scale.set(2.4,0.5,1);rlSp.visible=false;scene.add(rlSp);
        rackLabels.push({sprite:rlSp,canvas:rlc,texture:rlTex});
      }
      function updateDynLabel(lb,text,color,x,y,z){
        var ctx=lb.canvas.getContext('2d');
        var cW=lb.canvas.width,cH=lb.canvas.height;
        ctx.clearRect(0,0,cW,cH);
        ctx.fillStyle='rgba(0,0,0,0.75)';
        ctx.fillRect(8,6,cW-16,cH-12);
        // 자동 폰트 크기 (텍스트 길이에 맞춤)
        var fs=28;
        ctx.font='bold '+fs+'px monospace';
        while(ctx.measureText(text).width>cW-24&&fs>12){fs-=2;ctx.font='bold '+fs+'px monospace';}
        ctx.textAlign='center';ctx.textBaseline='middle';
        ctx.fillStyle=color;ctx.fillText(text,cW/2,cH/2);
        lb.texture.needsUpdate=true;
        lb.sprite.position.set(x,y,z);
        lb.sprite.visible=true;
      }

      // --- 워크스루 상태 ---
      var walkState = {
        active: false,
        posX: 0, posZ: 0,
        angle: Math.PI/2,
        speed: 0.06,
        turnSpeed: 0.04,
        keys: {w:false,a:false,s:false,d:false,q:false,e:false},
        colliding: false,
        nearestL: 999, nearestR: 999, nearestF: 999,
        collideName: '',
        camTheta: 0, camPhi: 0.35, camDist: 4,
        nearRack: '',
        // 미니맵용 창고 치수 (미터)
        whw:whw, whh:whh, jy:jy, rx:rx,
        colliders: colliders
      };
      view3dWalkRef.current = walkState;

      // 자키의 AABB 구하기 (월드좌표)
      function getJackAABB(px,pz,ang){
        // 자키+파렛트 합산: 폭 1.1m, 길이 1.4m (파렛트1.1 + 펌프0.3)
        var hw=palletW/2+0.05, hd=(palletD+pumpD)/2+0.05;// 반폭, 반길이
        // 회전된 4개 코너의 AABB
        var cos=Math.cos(ang),sin=Math.sin(ang);
        var corners=[[-hw,-hd],[hw,-hd],[hw,hd],[-hw,hd]];
        var mnX=1e9,mxX=-1e9,mnZ=1e9,mxZ=-1e9;
        corners.forEach(function(c){
          var rx=c[0]*cos-c[1]*sin+px;
          var rz=c[0]*sin+c[1]*cos+pz;
          if(rx<mnX)mnX=rx;if(rx>mxX)mxX=rx;
          if(rz<mnZ)mnZ=rz;if(rz>mxZ)mxZ=rz;
        });
        return {minX:mnX,maxX:mxX,minZ:mnZ,maxZ:mxZ};
      }

      // 충돌 검사
      function checkCollision(px,pz,ang){
        var bb=getJackAABB(px,pz,ang);
        for(var i=0;i<colliders.length;i++){
          var c=colliders[i];
          if(c.passable) continue;// DOOR/PLT는 통과 가능
          if(bb.maxX>c.minX&&bb.minX<c.maxX&&bb.maxZ>c.minZ&&bb.minZ<c.maxZ){
            return {hit:true,name:c.name};
          }
        }
        return {hit:false,name:''};
      }

      // 좌우/전방 클리어런스 계산 (레이캐스트)
      function calcClearance(px,pz,ang){
        var cos=Math.cos(ang),sin=Math.sin(ang);
        var leftDir=[-cos,-sin];
        var rightDir=[cos,sin];
        var fwdDir=[Math.sin(ang),Math.cos(ang)];
        var hw=palletW/2+0.05;
        var lEdgeX=px+leftDir[0]*hw, lEdgeZ=pz+leftDir[1]*hw;
        var rEdgeX=px+rightDir[0]*hw, rEdgeZ=pz+rightDir[1]*hw;
        var fEdgeX=px+fwdDir[0]*(palletD/2+0.1), fEdgeZ=pz+fwdDir[1]*(palletD/2+0.1);
        var nearL=raycastAll(lEdgeX,lEdgeZ,leftDir);
        var nearR=raycastAll(rEdgeX,rEdgeZ,rightDir);
        var nearF=raycastAll(fEdgeX,fEdgeZ,fwdDir);
        return {l:nearL,r:nearR,f:nearF};
      }

      // 모든 collider + 건물 경계에 대한 레이캐스트
      function raycastAll(ox,oz,dir){
        var minD=999;
        // 1) 건물 경계선에 대한 레이캐스트 (L자 형태 6개 변)
        var segs=[[0,0,whw,0],[whw,0,whw,jy],[whw,jy,rx,jy],[rx,jy,rx,whh],[rx,whh,0,whh],[0,whh,0,0]];
        segs.forEach(function(s){
          var d=raySegment(ox,oz,dir[0],dir[1],s[0],s[1],s[2],s[3]);
          if(d>0&&d<minD) minD=d;
        });
        // 2) 장애물 박스에 대한 AABB 레이캐스트
        colliders.forEach(function(c){
          if(c.name&&c.name.indexOf('wall')===0) return;// 벽 collider는 이미 경계선으로 처리
          var d=rayAABB(ox,oz,dir,c);
          if(d>0&&d<minD) minD=d;
        });
        return minD;
      }

      // 레이 vs 선분 교차 (2D)
      function raySegment(ox,oz,dx,dz,ax,az,bx,bz){
        var sx=bx-ax,sz=bz-az;
        var denom=dx*sz-dz*sx;
        if(Math.abs(denom)<1e-8) return 999;// 평행
        var t=((ax-ox)*sz-(az-oz)*sx)/denom;
        var u=((ax-ox)*dz-(az-oz)*dx)/denom;
        if(t>0.001&&u>=0&&u<=1) return t;
        return 999;
      }

      // 레이 vs AABB 교차 (2D)
      function rayAABB(ox,oz,dir,box){
        var tmin=-1e9,tmax=1e9;
        // X slab
        if(Math.abs(dir[0])>1e-8){
          var t1=(box.minX-ox)/dir[0],t2=(box.maxX-ox)/dir[0];
          if(t1>t2){var tmp=t1;t1=t2;t2=tmp;}
          tmin=Math.max(tmin,t1);tmax=Math.min(tmax,t2);
        } else {
          if(ox<box.minX||ox>box.maxX) return 999;
        }
        // Z slab
        if(Math.abs(dir[1])>1e-8){
          var t3=(box.minZ-oz)/dir[1],t4=(box.maxZ-oz)/dir[1];
          if(t3>t4){var tmp2=t3;t3=t4;t4=tmp2;}
          tmin=Math.max(tmin,t3);tmax=Math.min(tmax,t4);
        } else {
          if(oz<box.minZ||oz>box.maxZ) return 999;
        }
        if(tmax<0||tmin>tmax) return 999;
        return tmin>0?tmin:tmax>0?tmax:999;
      }

      // 워크스루 업데이트 (매 프레임)
      function updateWalkthrough(){
        if(!walkState.active)return;
        var k=walkState.keys;
        var newX=walkState.posX, newZ=walkState.posZ, newAng=walkState.angle;
        // 회전
        if(k.q) newAng+=walkState.turnSpeed;
        if(k.e) newAng-=walkState.turnSpeed;
        // 전진/후진
        var fwdX=Math.sin(newAng),fwdZ=Math.cos(newAng);
        if(k.w){newX+=fwdX*walkState.speed;newZ+=fwdZ*walkState.speed;}
        if(k.s){newX-=fwdX*walkState.speed;newZ-=fwdZ*walkState.speed;}
        // 좌우 이동 (스트레이프)
        var sideX=Math.cos(newAng),sideZ=-Math.sin(newAng);
        if(k.a){newX+=sideX*walkState.speed;newZ+=sideZ*walkState.speed;}
        if(k.d){newX-=sideX*walkState.speed;newZ-=sideZ*walkState.speed;}

        // 충돌 검사 (슬라이딩 + 끼임 탈출)
        var col=checkCollision(newX,newZ,newAng);
        if(!col.hit){
          // 이동 성공
          walkState.colliding=false;walkState.collideName='';
          walkState.posX=newX;walkState.posZ=newZ;walkState.angle=newAng;
          jackBoundVis.material.color.setHex(0x00ff00);jackBoundVis.material.opacity=0.2;
        } else {
          // X축만 이동 시도 (벽을 따라 미끄러짐)
          var colX=checkCollision(newX,walkState.posZ,newAng);
          var colZ=checkCollision(walkState.posX,newZ,newAng);
          if(!colX.hit){
            walkState.posX=newX;walkState.angle=newAng;
            walkState.colliding=false;walkState.collideName='';
            jackBoundVis.material.color.setHex(0xffaa00);jackBoundVis.material.opacity=0.3;
          } else if(!colZ.hit){
            walkState.posZ=newZ;walkState.angle=newAng;
            walkState.colliding=false;walkState.collideName='';
            jackBoundVis.material.color.setHex(0xffaa00);jackBoundVis.material.opacity=0.3;
          } else {
            // 끼임 상태: 가장 가까운 장애물 반대 방향으로 밀어내기 시도
            walkState.angle=newAng;// 회전은 항상 허용
            var bb=getJackAABB(walkState.posX,walkState.posZ,newAng);
            var pushX=0,pushZ=0,pushCount=0;
            for(var ci=0;ci<colliders.length;ci++){
              var c=colliders[ci];
              if(c.passable) continue;
              if(bb.maxX>c.minX&&bb.minX<c.maxX&&bb.maxZ>c.minZ&&bb.minZ<c.maxZ){
                // 겹치는 충돌체에서 밀어내기 방향 계산
                var cx=(c.minX+c.maxX)/2,cz=(c.minZ+c.maxZ)/2;
                var dx=walkState.posX-cx,dz=walkState.posZ-cz;
                var dl=Math.sqrt(dx*dx+dz*dz)||1;
                pushX+=dx/dl;pushZ+=dz/dl;pushCount++;
              }
            }
            if(pushCount>0){
              pushX/=pushCount;pushZ/=pushCount;
              var pushSpd=walkState.speed*0.8;
              var tryX=walkState.posX+pushX*pushSpd;
              var tryZ=walkState.posZ+pushZ*pushSpd;
              if(!checkCollision(tryX,tryZ,newAng).hit){
                walkState.posX=tryX;walkState.posZ=tryZ;
                walkState.colliding=false;walkState.collideName='';
                jackBoundVis.material.color.setHex(0xff8800);jackBoundVis.material.opacity=0.3;
              } else {
                walkState.colliding=true;walkState.collideName=col.name;
                jackBoundVis.material.color.setHex(0xff0000);jackBoundVis.material.opacity=0.4;
              }
            } else {
              walkState.colliding=true;walkState.collideName=col.name;
              jackBoundVis.material.color.setHex(0xff0000);jackBoundVis.material.opacity=0.4;
            }
          }
        }

        // 모델 위치 업데이트
        jackGroup.position.set(walkState.posX,0,walkState.posZ);
        jackGroup.rotation.y=walkState.angle;

        // 클리어런스 계산
        var cl=calcClearance(walkState.posX,walkState.posZ,walkState.angle);
        walkState.nearestL=cl.l;walkState.nearestR=cl.r;walkState.nearestF=cl.f;

        // 클리어런스 라인 업데이트
        var cos=Math.cos(walkState.angle),sin=Math.sin(walkState.angle);
        var leftDir=[-cos,-sin],rightDir=[cos,sin];
        var hw=palletW/2+0.05;
        var lx=walkState.posX+leftDir[0]*hw,lz=walkState.posZ+leftDir[1]*hw;
        var rx2=walkState.posX+rightDir[0]*hw,rz2=walkState.posZ+rightDir[1]*hw;
        var dL=Math.min(cl.l,3),dR=Math.min(cl.r,3);
        clearLineL.geometry.dispose();
        clearLineL.geometry=new THREE.BufferGeometry().setFromPoints([
          new THREE.Vector3(lx,0.3,lz),
          new THREE.Vector3(lx+leftDir[0]*dL,0.3,lz+leftDir[1]*dL)
        ]);
        clearLineL.material.color.setHex(cl.l<0.3?0xff0000:cl.l<0.5?0xffaa00:0x00ff00);
        clearLineR.geometry.dispose();
        clearLineR.geometry=new THREE.BufferGeometry().setFromPoints([
          new THREE.Vector3(rx2,0.3,rz2),
          new THREE.Vector3(rx2+rightDir[0]*dR,0.3,rz2+rightDir[1]*dR)
        ]);
        clearLineR.material.color.setHex(cl.r<0.3?0xff0000:cl.r<0.5?0xffaa00:0x00ff00);
        // 전방 클리어런스 라인
        var fwdDirV=[Math.sin(walkState.angle),Math.cos(walkState.angle)];
        var fEdge=palletD/2+0.1;
        var fx=walkState.posX+fwdDirV[0]*fEdge,fz=walkState.posZ+fwdDirV[1]*fEdge;
        var dF=Math.min(cl.f,3);
        clearLineF.geometry.dispose();
        clearLineF.geometry=new THREE.BufferGeometry().setFromPoints([
          new THREE.Vector3(fx,0.3,fz),
          new THREE.Vector3(fx+fwdDirV[0]*dF,0.3,fz+fwdDirV[1]*dF)
        ]);
        clearLineF.material.color.setHex(cl.f<0.3?0xff0000:cl.f<0.5?0xffaa00:0x00ff00);
        // 3D 거리 라벨 업데이트
        var fmtD=function(d){return d>=100?'∞':Math.round(d*1000)+'mm';};
        var clrHex=function(d){return d<0.3?'#f87171':d<0.5?'#fbbf24':'#4ade80';};
        updateDynLabel(labelL,'◀ '+fmtD(cl.l),clrHex(cl.l),lx+leftDir[0]*Math.min(dL,1.5),0.6,lz+leftDir[1]*Math.min(dL,1.5));
        updateDynLabel(labelR,fmtD(cl.r)+' ▶',clrHex(cl.r),rx2+rightDir[0]*Math.min(dR,1.5),0.6,rz2+rightDir[1]*Math.min(dR,1.5));
        updateDynLabel(labelF,'▲ '+fmtD(cl.f),clrHex(cl.f),fx+fwdDirV[0]*Math.min(dF,1.5),0.6,fz+fwdDirV[1]*Math.min(dF,1.5));

        // 근접 랙 정보 표시 (2m 이내)
        var nearRacks=[];
        rackInfos.forEach(function(ri){
          var dx=ri.x-walkState.posX,dz=ri.z-walkState.posZ;
          var dist2=Math.sqrt(dx*dx+dz*dz);
          if(dist2<2.5) nearRacks.push({info:ri,dist:dist2});
        });
        nearRacks.sort(function(a,b){return a.dist-b.dist;});
        for(var rli=0;rli<3;rli++){
          if(rli<nearRacks.length){
            var nr=nearRacks[rli];
            var sName=SERIES_NAMES[nr.info.series]||nr.info.series;
            var sCol=SERIES_HEX[nr.info.series]||'#ffffff';
            var txt=SERIES_NAMES[nr.info.series]||nr.info.series;
            updateDynLabel(rackLabels[rli],txt,sCol,nr.info.x,2.2,nr.info.z);
          } else {
            rackLabels[rli].sprite.visible=false;
          }
        }
        walkState.nearRack=nearRacks.length>0?(SERIES_NAMES[nearRacks[0].info.series]||nearRacks[0].info.series):'';

        // 카메라: 3인칭 팔로우 (마우스로 시점 변경 가능)
        var camH=walkState.camDist*Math.sin(walkState.camPhi);
        var camHoriz=walkState.camDist*Math.cos(walkState.camPhi);
        var totalAng=walkState.angle;
        var behindX=walkState.posX-Math.sin(totalAng)*camHoriz;
        var behindZ=walkState.posZ-Math.cos(totalAng)*camHoriz;
        camera.position.set(behindX,camH,behindZ);
        camera.lookAt(walkState.posX,0.5,walkState.posZ);
      }

      // 워크스루 시작 위치: 첫 번째 DOOR 아래 통로 중앙
      var startDoor=null;
      if(layoutData.R){
        var allDoors2=layoutData.R.filter(function(r){return (r.a||'').toUpperCase().indexOf('DOOR')>=0;});
        startDoor=allDoors2.length>0?allDoors2.reduce(function(a,b){return a.y<b.y?a:b;}):null;
      }
      // DOOR 위치에서 창고 안쪽으로 5m, Packaging Foam과 Injection 사이 통로 중앙
      var walkStartX=startDoor?toM(startDoor.x-BX3D)+toM(rpx3d(startDoor).w)/2:3;
      var walkStartZ=startDoor?toM(startDoor.y-BY3D)+5:5;
      // 충돌 없는 스폰 지점 찾기 (나선형 탐색)
      function findSafeSpawn(cx,cz){
        var ang=Math.PI/2;
        if(!checkCollision(cx,cz,ang).hit) return {x:cx,z:cz};
        for(var r=0.5;r<=5;r+=0.5){
          for(var a=0;a<Math.PI*2;a+=Math.PI/6){
            var tx=cx+Math.cos(a)*r, tz=cz+Math.sin(a)*r;
            if(!checkCollision(tx,tz,ang).hit) return {x:tx,z:tz};
          }
        }
        return {x:cx+3,z:cz+3};// fallback
      }
      var safeSpawn=findSafeSpawn(walkStartX,walkStartZ);
      walkStartX=safeSpawn.x; walkStartZ=safeSpawn.z;

      // 토글 함수 노출
      view3dCtrlRef.current.toggleWalk = function(){
        walkState.active=!walkState.active;
        jackGroup.visible=walkState.active;
        clearLineL.visible=walkState.active;
        clearLineR.visible=walkState.active;
        clearLineF.visible=walkState.active;
        labelL.sprite.visible=walkState.active;
        labelR.sprite.visible=walkState.active;
        labelF.sprite.visible=walkState.active;
        rackLabels.forEach(function(rl){rl.sprite.visible=false;});
        if(walkState.active){
          var sp=findSafeSpawn(walkStartX,walkStartZ);
          walkState.posX=sp.x;walkState.posZ=sp.z;
          walkState.angle=0;// 오른쪽(+Z 방향, 창고 안쪽)
          walkState.keys={w:false,a:false,s:false,d:false,q:false,e:false};
          walkState.colliding=false;walkState.collideName='';
          walkState.camTheta=0;walkState.camPhi=0.35;walkState.camDist=4;
          jackGroup.position.set(walkState.posX,0,walkState.posZ);
          jackGroup.rotation.y=walkState.angle;
        } else {
          // 오빗 모드로 복원
          theta=0.8;phi=0.5;dist=35;target.set(whw/2,0,whh/3);
          updateCam();
        }
        return walkState.active;
      };
      view3dCtrlRef.current.getWalkState = function(){return walkState;};
      view3dCtrlRef.current.resetWalkCam = function(){
        walkState.camTheta=0;walkState.camPhi=0.35;walkState.camDist=4;
      };
      view3dCtrlRef.current.resetWalkPos = function(){
        var sp=findSafeSpawn(walkStartX,walkStartZ);
        walkState.posX=sp.x;walkState.posZ=sp.z;
        walkState.angle=0;
        walkState.colliding=false;walkState.collideName='';
        jackGroup.position.set(walkState.posX,0,walkState.posZ);
        jackGroup.rotation.y=walkState.angle;
      };
      // 스크린샷 캡처
      view3dCtrlRef.current.captureScreenshot = function(){
        renderer.render(scene,camera);
        try{
          cv.toBlob(function(blob){
            if(!blob)return;
            var url=URL.createObjectURL(blob);
            var a=document.createElement('a');
            a.href=url;
            var now=new Date();
            var pad=function(n){return n<10?'0'+n:''+n;};
            a.download='warehouse_3d_'+now.getFullYear()+pad(now.getMonth()+1)+pad(now.getDate())+'_'+pad(now.getHours())+pad(now.getMinutes())+'.png';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            setTimeout(function(){URL.revokeObjectURL(url);},1000);
          },'image/png');
        }catch(e){
          // fallback: 새 탭에 이미지 열기
          var dataUrl=cv.toDataURL('image/png');
          window.open(dataUrl,'_blank');
        }
      };

      const animate=()=>{if(!view3dSceneRef.current)return;requestAnimationFrame(animate);updateWalkthrough();renderer.render(scene,camera);};
      animate();
    };
    if(!window.THREE){const sc=document.createElement('script');sc.src='https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js';sc.onload=loadAndInit;document.head.appendChild(sc);}else{loadAndInit();}
    return () => {
      if(view3dKeyRef.current){window.removeEventListener('keydown',view3dKeyRef.current.down);window.removeEventListener('keyup',view3dKeyRef.current.up);view3dKeyRef.current=null;}
      if(view3dWalkRef.current){view3dWalkRef.current.active=false;view3dWalkRef.current=null;}
      if(view3dSceneRef.current){view3dSceneRef.current.renderer.dispose();view3dSceneRef.current=null;}
    };
  }, [activeTab, layoutData]);

