            <div className="flex-shrink-0 border-t p-4 flex justify-end">
              <button onClick={() => setShowPickDetailModal(false)} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">
                닫기
              </button>
            </div>
